  },
  "visualReliability": {
    "value": "sufficient-for-focus",
    "limits": [
      "本轮直接确认水簿摊开、墨迹尚湿，足以支持纸面局部。",
      "签名已经完成。落笔时的手势、字形、具体条款、此刻的光照与视角均缺少直接依据。"
    ]
  },
  "timingIntent": "text-only",
